// spec: specs/admin-panel.md
// seed: tests/seed.support.spec.ts
import { test, expect } from '@playwright/test';

test.use({ storageState: '../auth/support.json' });

test.describe('1. Админ-панель — матрица прав и спец. действия', () => {
  test('1.1 Support видит только Users, поля read-only, есть «Send a password reset», нет «Add user» @desktop @prod-safe (#6a8a96c821e5a64ca7a411dd)', async ({ page }) => {
    // 1. Guard сессии (см. выше), открыть `/admin`.
    await page.goto('/admin');
    const url = page.url();
    const mfa = await page.getByText(/verification code|authenticator|MFA|קוד אימות/i).first().isVisible().catch(() => false);
    test.skip(/\/(welcome|sign-in)/.test(url) || mfa, 'Сессия support не авторизована (истекла / нужен MFA): npm run qa-login:manual -- support');

    // 2. Посмотреть боковое меню.
    const usersItem = page.getByText(/^(Users|משתמשים)$/).first();
    await expect(usersItem).toBeVisible();
    await expect(page.getByText(/Billing|חיוב|חיובים/)).toHaveCount(0);
    await expect(page.getByText(/Advertising|פרסום/)).toHaveCount(0);
    await expect(page.getByText(/Reports|דוחות|דיווחים/)).toHaveCount(0);
    await expect(page.getByText(/Audit log|יומן ביקורת/)).toHaveCount(0);

    // 3. Открыть раздел Users, найти «John Doe», открыть карточку.
    await usersItem.click();
    await expect(page.getByRole('button', { name: /Add user|הוספת משתמש/ })).toHaveCount(0);
    await page.getByRole('searchbox').or(page.getByRole('textbox')).first().fill('John Doe');
    await page.getByText('John Doe').first().click();

    // Карточка: Send a password reset есть (не нажимать)
    await expect(page.getByRole('button', { name: /Send a password reset|שליחת איפוס סיסמה/ })).toBeVisible();
    // Поля только для чтения, опасных кнопок нет
    await expect(page.getByRole('button', { name: /^(Save|שמירה)$/ })).toHaveCount(0);
    await expect(page.getByRole('button', { name: /Suspend|השעיה/ })).toHaveCount(0);
    await expect(page.getByRole('button', { name: /Block|חסימה/ })).toHaveCount(0);
    await expect(page.getByRole('button', { name: /Delete user|מחיקת משתמש/ })).toHaveCount(0);
    await expect(page.getByRole('button', { name: /Issue a password code|הנפקת קוד סיסמה/ })).toHaveCount(0);
    await expect(page.getByRole('combobox', { name: /Role|תפקיד/ })).toHaveCount(0);
  });
});
